-- Reconstructed schema version 3 fixture for the v3 to v6 upgrade path.
-- Derived from schema_v5.sql by removing the columns added after v3:
--   user_preferences.north_reference                (added in v4)
--   user_preferences.default_star_sharpness         (added in v5)
--   user_preferences.default_alignment_tolerance_degrees (added in v5)
-- camera_bodies.notes is already absent here because the v5 fixture predates v6.
-- Representative data is included so the migration's defaults can be asserted.
BEGIN TRANSACTION;
CREATE TABLE "calculation_snapshots" ("id" TEXT NOT NULL, "calculator_id" TEXT NOT NULL, "formula_version" INTEGER NOT NULL CHECK("formula_version" > 0), "created_at" INTEGER NOT NULL, "title" TEXT NOT NULL, "notes" TEXT NULL, "payload_version" INTEGER NOT NULL CHECK("payload_version" > 0), "input_payload" TEXT NOT NULL, "output_payload" TEXT NOT NULL, "display_context" TEXT NOT NULL, "assumptions" TEXT NOT NULL, "warnings" TEXT NOT NULL, "equipment_snapshot" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "camera_bodies" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "normalized_name" TEXT NOT NULL, "source_type" TEXT NOT NULL CHECK("source_type" IN ('user', 'bundled', 'user_override')), "source_note" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "archived_at" INTEGER NULL, "sensor_width_mm" REAL NOT NULL CHECK("sensor_width_mm" > 0.0), "sensor_height_mm" REAL NOT NULL CHECK("sensor_height_mm" > 0.0), "default_circle_of_confusion_mm" REAL NULL CHECK("default_circle_of_confusion_mm" IS NULL OR "default_circle_of_confusion_mm" > 0.0), PRIMARY KEY ("id"));
INSERT INTO "camera_bodies" VALUES('legacy-camera','Legacy camera','legacy camera','user','Legacy provenance',1787270400,1787270400,NULL,36.0,24.0,0.03);
CREATE TABLE "lenses" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "normalized_name" TEXT NOT NULL, "source_type" TEXT NOT NULL CHECK("source_type" IN ('user', 'bundled', 'user_override')), "source_note" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "archived_at" INTEGER NULL, "minimum_focal_length_mm" REAL NOT NULL CHECK("minimum_focal_length_mm" > 0.0), "maximum_focal_length_mm" REAL NOT NULL CHECK("maximum_focal_length_mm" >= "minimum_focal_length_mm"), "minimum_aperture" REAL NULL, "maximum_focal_length_minimum_aperture" REAL NULL, "minimum_focus_distance_mm" REAL NULL, "notes" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "nd_filters" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "normalized_name" TEXT NOT NULL, "source_type" TEXT NOT NULL CHECK("source_type" IN ('user', 'bundled', 'user_override')), "source_note" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "archived_at" INTEGER NULL, "strength_stops" REAL NOT NULL CHECK("strength_stops" >= 0.0), "optical_density" REAL NULL, "filter_factor" REAL NULL, "notes" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "optical_accessories" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "normalized_name" TEXT NOT NULL, "source_type" TEXT NOT NULL CHECK("source_type" IN ('user', 'bundled', 'user_override')), "source_note" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "archived_at" INTEGER NULL, "kind" TEXT NOT NULL CHECK("kind" IN ('extension_tube', 'teleconverter')), "value" REAL NOT NULL CHECK("value" > 0.0), "notes" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "saved_locations" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "normalized_name" TEXT NOT NULL, "latitude_degrees" REAL NOT NULL CHECK("latitude_degrees" >= -90.0 AND "latitude_degrees" <= 90.0), "longitude_degrees" REAL NOT NULL CHECK("longitude_degrees" >= -180.0 AND "longitude_degrees" <= 180.0), "elevation_metres" REAL NULL, "time_zone_id" TEXT NOT NULL, "source" TEXT NOT NULL CHECK("source" IN ('manual', 'device')), "accuracy_metres" REAL NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
INSERT INTO "saved_locations" VALUES('legacy-location','Legacy site','legacy site',-33.8688,151.2093,20.0,'Australia/Sydney','manual',NULL,1787270400,1787270400);
CREATE TABLE "snapshot_equipment_references" ("snapshot_id" TEXT NOT NULL REFERENCES calculation_snapshots (id) ON DELETE CASCADE, "equipment_id" TEXT NOT NULL, "equipment_type" TEXT NOT NULL CHECK("equipment_type" IN ('camera', 'lens', 'nd_filter', 'optical_accessory')), "display_order" INTEGER NOT NULL CHECK("display_order" >= 0), PRIMARY KEY ("snapshot_id", "equipment_id", "equipment_type"));
CREATE TABLE "user_preferences" ("id" INTEGER NOT NULL DEFAULT 1, "length_display" TEXT NOT NULL DEFAULT 'metric', "shutter_display" TEXT NOT NULL DEFAULT 'exact', "fraction_step" TEXT NOT NULL DEFAULT 'third', "theme_mode" TEXT NOT NULL DEFAULT 'system', "favorite_tool_ids" TEXT NOT NULL DEFAULT '[]', PRIMARY KEY ("id"), CHECK (id = 1));
INSERT INTO "user_preferences" VALUES(1,'imperial','conventional','half','lowLight','["astronomy"]');
CREATE UNIQUE INDEX active_camera_name ON camera_bodies(normalized_name) WHERE archived_at IS NULL;
CREATE UNIQUE INDEX active_lens_name ON lenses(normalized_name) WHERE archived_at IS NULL;
CREATE UNIQUE INDEX active_nd_filter_name ON nd_filters(normalized_name) WHERE archived_at IS NULL;
CREATE UNIQUE INDEX active_optical_accessory_name ON optical_accessories(normalized_name) WHERE archived_at IS NULL;
CREATE UNIQUE INDEX saved_location_name ON saved_locations(normalized_name);
COMMIT;
PRAGMA user_version = 3;
